using System;using System.IO;using System.Linq;using System.Reflection;using System.Diagnostics;using System.Threading.Tasks;
// Windows PDF adapter only. Framework WinRT projection; no third-party renderer.
class NativePdf {
 static object Await(object operation,Type result){var method=typeof(System.WindowsRuntimeSystemExtensions).GetMethods().First(x=>x.Name=="AsTask"&&x.IsGenericMethodDefinition&&x.GetParameters().Length==1&&x.GetParameters()[0].ParameterType.Name=="IAsyncOperation`1");var task=(Task)method.MakeGenericMethod(result).Invoke(null,new object[]{operation});task.GetAwaiter().GetResult();return task.GetType().GetProperty("Result").GetValue(task,null);}
 static void AwaitAction(object operation){var method=typeof(System.WindowsRuntimeSystemExtensions).GetMethods().First(x=>x.Name=="AsTask"&&!x.IsGenericMethod&&x.GetParameters().Length==1&&x.GetParameters()[0].ParameterType.Name=="IAsyncAction");((Task)method.Invoke(null,new object[]{operation})).GetAwaiter().GetResult();}
 static Type WinType(string name,string assembly){return Type.GetType(name+", "+assembly+", ContentType=WindowsRuntime",true);}
 static void Render(object pdf,Type pdfType,uint number,string output){var page=pdfType.GetMethod("GetPage").Invoke(pdf,new object[]{number});var streamType=WinType("Windows.Storage.Streams.InMemoryRandomAccessStream","Windows.Storage.Streams");var stream=Activator.CreateInstance(streamType);try{var optionsType=WinType("Windows.Data.Pdf.PdfPageRenderOptions","Windows.Data.Pdf");var options=Activator.CreateInstance(optionsType);var size=page.GetType().GetProperty("Size").GetValue(page,null);var width=Convert.ToDouble(size.GetType().GetProperty("Width").GetValue(size,null));var height=Convert.ToDouble(size.GetType().GetProperty("Height").GetValue(size,null));var scale=1800/Math.Max(width,height);optionsType.GetProperty("DestinationWidth").SetValue(options,(uint)Math.Max(1,width*scale),null);optionsType.GetProperty("DestinationHeight").SetValue(options,(uint)Math.Max(1,height*scale),null);var render=page.GetType().GetMethods().First(x=>x.Name=="RenderToStreamAsync"&&x.GetParameters().Length==2);AwaitAction(render.Invoke(page,new object[]{stream,options}));streamType.GetMethod("Seek").Invoke(stream,new object[]{(ulong)0});var asStream=typeof(System.IO.WindowsRuntimeStreamExtensions).GetMethods().First(x=>x.Name=="AsStreamForRead"&&x.GetParameters().Length==1&&x.GetParameters()[0].ParameterType.Name=="IInputStream");using(var input=(Stream)asStream.Invoke(null,new object[]{stream}))using(var file=File.Create(output))input.CopyTo(file);}finally{((IDisposable)page).Dispose();((IDisposable)stream).Dispose();}}
 [STAThread] static int Main(string[] args){try{var storage=WinType("Windows.Storage.StorageFile","Windows.Storage");var pdfType=WinType("Windows.Data.Pdf.PdfDocument","Windows.Data.Pdf");var file=Await(storage.GetMethod("GetFileFromPathAsync").Invoke(null,new object[]{args[1]}),storage);var pdf=Await(pdfType.GetMethod("LoadFromFileAsync",new Type[]{storage}).Invoke(null,new object[]{file}),pdfType);Console.WriteLine(pdfType.GetProperty("PageCount").GetValue(pdf,null));Console.Out.Flush();if(args[0]=="info")return 0;if(args[0]=="render"){Render(pdf,pdfType,uint.Parse(args[2]),args[3]);return 0;}string line;while((line=Console.ReadLine())!=null&&line!="QUIT"){try{var parts=line.Split('|');var watch=Stopwatch.StartNew();Render(pdf,pdfType,uint.Parse(parts[0]),parts[1]);Console.WriteLine("OK "+watch.ElapsedMilliseconds);}catch(Exception e){Console.WriteLine("ERROR "+e.GetBaseException().Message.Replace('\n',' '));}Console.Out.Flush();}return 0;}catch(Exception e){Console.Error.WriteLine(e.GetBaseException().ToString());return 1;}}
}
